158	template <typename FPTYPE>
159	void deepmd::tabulate_fusion_se_a_grad_cpu(FPTYPE* dy_dem_x,
160	                                           FPTYPE* dy_dem,
161	                                           FPTYPE* dy_dtwo,
162	                                           const FPTYPE* table,
163	                                           const FPTYPE* table_info,
164	                                           const FPTYPE* em_x,
165	                                           const FPTYPE* em,
166	                                           const FPTYPE* two_embed,
167	                                           const FPTYPE* dy,
168	                                           const int nloc,
169	                                           const int nnei,
170	                                           const int last_layer_size,
171	                                           const bool is_sorted) {
172	  bool enable_se_atten = two_embed != nullptr;
173	  memset(dy_dem_x, 0, sizeof(FPTYPE) * nloc * nnei);
174	  memset(dy_dem, 0, sizeof(FPTYPE) * nloc * nnei * 4);
175	  if (enable_se_atten) {
176	    memset(dy_dtwo, 0, sizeof(FPTYPE) * nloc * nnei * last_layer_size);
177	  }
178	  FPTYPE const lower = table_info[0];
179	  FPTYPE const upper = table_info[1];
180	  FPTYPE const _max = table_info[2];
181	  FPTYPE const stride0 = table_info[3];
182	  FPTYPE const stride1 = table_info[4];
183	// for every atom, execute a small gemm~
184	// FPTYPE * res = new FPTYPE[4 * last_layer_size];
185	#pragma omp parallel for
186	  for (int ii = 0; ii < nloc; ii++) {
187	    FPTYPE ll[4];
188	    FPTYPE rr[4];
189	    FPTYPE ago = em_x[ii * nnei + nnei - 1];
190	    bool unloop = false;
191	    for (int jj = 0; jj < nnei; jj++) {
192	      // construct the dy/dx
193	      ll[0] = em[ii * nnei * 4 + jj * 4 + 0];
194	      ll[1] = em[ii * nnei * 4 + jj * 4 + 1];
195	      ll[2] = em[ii * nnei * 4 + jj * 4 + 2];
196	      ll[3] = em[ii * nnei * 4 + jj * 4 + 3];
197	      FPTYPE xx = em_x[ii * nnei + jj];
198	      if (ago == xx && ll[1] == 0. && ll[2] == 0. && ll[3] == 0. && is_sorted) {
199	        unloop = true;
200	      }
201	      int table_idx = 0;
202	      locate_xx(lower, upper, _max, stride0, stride1, xx, table_idx);
203	      FPTYPE grad = (FPTYPE)0.0;
204	      for (int kk = 0; kk < last_layer_size; kk++) {
205	        rr[0] = dy[ii * last_layer_size * 4 + 0 * last_layer_size + kk];
206	        rr[1] = dy[ii * last_layer_size * 4 + 1 * last_layer_size + kk];
207	        rr[2] = dy[ii * last_layer_size * 4 + 2 * last_layer_size + kk];
208	        rr[3] = dy[ii * last_layer_size * 4 + 3 * last_layer_size + kk];
209	        FPTYPE a0 = table[table_idx * last_layer_size * 6 + 6 * kk + 0];
210	        FPTYPE a1 = table[table_idx * last_layer_size * 6 + 6 * kk + 1];
211	        FPTYPE a2 = table[table_idx * last_layer_size * 6 + 6 * kk + 2];
212	        FPTYPE a3 = table[table_idx * last_layer_size * 6 + 6 * kk + 3];
213	        FPTYPE a4 = table[table_idx * last_layer_size * 6 + 6 * kk + 4];
214	        FPTYPE a5 = table[table_idx * last_layer_size * 6 + 6 * kk + 5];
215	        FPTYPE res =
216	            a0 + (a1 + (a2 + (a3 + (a4 + a5 * xx) * xx) * xx) * xx) * xx;
217	        FPTYPE g =
218	            (a1 + (2 * a2 + (3 * a3 + (4 * a4 + 5 * a5 * xx) * xx) * xx) * xx);
219	        FPTYPE resold = res;
220	        if (enable_se_atten) {
221	          FPTYPE t = two_embed[ii * nnei * last_layer_size +
222	                               jj * last_layer_size + kk];
223	          res = res * t + res;
224	          g += t * g;
225	        }
226	
227	        FPTYPE dotllrr = dot(ll, rr);
228	        if (unloop) {
229	          grad += g * dotllrr * (nnei - jj);
230	          dy_dem[ii * nnei * 4 + jj * 4 + 0] += res * rr[0] * (nnei - jj);
231	          dy_dem[ii * nnei * 4 + jj * 4 + 1] += res * rr[1] * (nnei - jj);
232	          dy_dem[ii * nnei * 4 + jj * 4 + 2] += res * rr[2] * (nnei - jj);
233	          dy_dem[ii * nnei * 4 + jj * 4 + 3] += res * rr[3] * (nnei - jj);
234	          if (enable_se_atten) {
235	            // fill from jj to nnei
236	            for (int jj2 = jj; jj2 < nnei; jj2++) {
237	              dy_dtwo[ii * nnei * last_layer_size + jj2 * last_layer_size +
238	                      kk] += resold * dotllrr;
239	            }
240	          }
241	        } else {
242	          grad += g * dotllrr;
243	          dy_dem[ii * nnei * 4 + jj * 4 + 0] += res * rr[0];
244	          dy_dem[ii * nnei * 4 + jj * 4 + 1] += res * rr[1];
245	          dy_dem[ii * nnei * 4 + jj * 4 + 2] += res * rr[2];
246	          dy_dem[ii * nnei * 4 + jj * 4 + 3] += res * rr[3];
247	          if (enable_se_atten) {
248	            dy_dtwo[ii * nnei * last_layer_size + jj * last_layer_size + kk] +=
249	                resold * dotllrr;
250	          }
251	        }
252	      }
253	      dy_dem_x[ii * nnei + jj] = grad;
254	      if (unloop) {
255	        break;
256	      }
257	    }
258	  }
259	}
