544	template <typename FPTYPE>
545	void deepmd::tabulate_fusion_se_t_tebd_cpu(FPTYPE* out,
546	                                           const FPTYPE* table,
547	                                           const FPTYPE* table_info,
548	                                           const FPTYPE* em_x,
549	                                           const FPTYPE* em,
550	                                           const int nloc,
551	                                           const int nnei_i,
552	                                           const int nnei_j,
553	                                           const int last_layer_size) {
554	  memset(out, 0, sizeof(FPTYPE) * nloc * nnei_i * nnei_j * last_layer_size);
555	  const FPTYPE lower = table_info[0];
556	  const FPTYPE upper = table_info[1];
557	  const FPTYPE _max = table_info[2];
558	  const FPTYPE stride0 = table_info[3];
559	  const FPTYPE stride1 = table_info[4];
560	
561	#pragma omp parallel for
562	  for (int ii = 0; ii < nloc; ii++) {
563	    for (int jj = 0; jj < nnei_i; jj++) {
564	      for (int kk = 0; kk < nnei_j; kk++) {
565	        FPTYPE xx = em_x[ii * nnei_i * nnei_j + jj * nnei_j + kk];
566	        int table_idx = 0;
567	        locate_xx_se_t(lower, upper, -_max, _max, stride0, stride1, xx,
568	                       table_idx);
569	
570	        // For SE_TEBD, we preserve the full nt_i x nt_j x ng structure
571	        // instead of reducing it like SE_T does
572	        for (int mm = 0; mm < last_layer_size; mm++) {
573	          FPTYPE a0 = table[table_idx * last_layer_size * 6 + 6 * mm + 0];
574	          FPTYPE a1 = table[table_idx * last_layer_size * 6 + 6 * mm + 1];
575	          FPTYPE a2 = table[table_idx * last_layer_size * 6 + 6 * mm + 2];
576	          FPTYPE a3 = table[table_idx * last_layer_size * 6 + 6 * mm + 3];
577	          FPTYPE a4 = table[table_idx * last_layer_size * 6 + 6 * mm + 4];
578	          FPTYPE a5 = table[table_idx * last_layer_size * 6 + 6 * mm + 5];
579	
580	          FPTYPE res = a0 + a1 * xx + a2 * xx * xx + a3 * xx * xx * xx +
581	                       a4 * xx * xx * xx * xx + a5 * xx * xx * xx * xx * xx;
582	
583	          // Store result preserving the nt_i x nt_j structure
584	          out[ii * nnei_i * nnei_j * last_layer_size +
585	              jj * nnei_j * last_layer_size + kk * last_layer_size + mm] = res;
586	        }
587	      }
588	    }
589	  }
590	}
