#include "tabulate.h"
#include <cmath>
#include <cstdio>
#include <functional>
#include <vector>

constexpr int kLastLayerSize = 3;
constexpr double kLower = -1.0;
constexpr double kUpper = 1.0;
constexpr double kMax = 2.8;
constexpr double kStride0 = 0.5;
constexpr double kStride1 = 0.6;
constexpr double kStep = 1.0e-6;

std::vector<double> make_table() {
  const int segment_count = 10;
  std::vector<double> table(segment_count * kLastLayerSize * 6);
  for (int segment = 0; segment < segment_count; ++segment) {
    for (int layer = 0; layer < kLastLayerSize; ++layer) {
      const int base = segment * kLastLayerSize * 6 + layer * 6;
      const double sign = (segment % 2 == 0) ? 1.0 : -1.0;
      table[base + 0] = 0.42 + 0.31 * segment - 0.07 * layer;
      table[base + 1] = sign * (0.83 + 0.11 * layer) + 0.03 * segment;
      table[base + 2] = -0.09 + 0.025 * segment + 0.015 * layer;
      table[base + 3] = 0.035 * (layer + 1) - 0.012 * segment;
      table[base + 4] = -0.006 * (segment + 1) + 0.002 * layer;
      table[base + 5] = 0.0015 * (segment % 3 - 1) + 0.0007 * (layer + 1);
    }
  }
  return table;
}

const std::vector<double> kTableInfo = {kLower, kUpper, kMax, kStride0, kStride1, -1.0};
const std::vector<double> kWeights = {0.72, -0.41, 0.23};
const std::vector<double> kEnv = {1.0, -0.24, 0.37, -0.18};
const std::vector<double> kAdjoint = {
    0.53, -0.17, 0.29, -0.31, 0.19, -0.11, 0.23, -0.07, 0.13, -0.05, 0.09, -0.21};

double dot(const std::vector<double>& l, const std::vector<double>& r) {
  double v = 0; for (size_t i = 0; i < l.size(); ++i) v += l[i]*r[i]; return v;
}

double radial_value(const std::vector<double>& table, double x) {
  std::vector<double> out(kLastLayerSize); const std::vector<double> em = {x};
  deepmd::tabulate_fusion_se_r_cpu<double>(out.data(), table.data(), kTableInfo.data(), em.data(), 1, 1, kLastLayerSize);
  return dot(out, kWeights);
}
double radial_sens(const std::vector<double>& table, double x) {
  std::vector<double> d(1); const std::vector<double> em = {x};
  deepmd::tabulate_fusion_se_r_grad_cpu<double>(d.data(), table.data(), kTableInfo.data(), em.data(), kWeights.data(), 1, 1, kLastLayerSize);
  return d[0];
}
double angular_value(const std::vector<double>& table, double x) {
  std::vector<double> out(4*kLastLayerSize); const std::vector<double> emx = {x};
  deepmd::tabulate_fusion_se_a_cpu<double>(out.data(), table.data(), kTableInfo.data(), emx.data(), kEnv.data(), nullptr, 1, 1, kLastLayerSize, false);
  return dot(out, kAdjoint);
}
double angular_sens(const std::vector<double>& table, double x) {
  std::vector<double> dx(1), dem(4), dtwo(1); const std::vector<double> emx = {x};
  deepmd::tabulate_fusion_se_a_grad_cpu<double>(dx.data(), dem.data(), dtwo.data(), table.data(), kTableInfo.data(), emx.data(), kEnv.data(), nullptr, kAdjoint.data(), 1, 1, kLastLayerSize, false);
  return dx[0];
}

void probe(const char* name, std::function<double(double)> f, std::function<double(double)> g) {
  const std::vector<double> pts = {kLower - 0.31, kLower - 0.17, kLower, kLower + 0.23, 0.15,
                                   kUpper + 0.34, kMax - 0.09, kMax, kMax + 0.17, kMax + 0.31};
  printf("== %s ==\n", name);
  printf("%10s %14s %14s %14s %14s %14s %12s\n", "x", "value", "sens", "cfd", "left", "right", "gap");
  for (double x : pts) {
    double v = f(x), s = g(x);
    double cfd = (f(x+kStep)-f(x-kStep))/(2*kStep);
    double left = (f(x)-f(x-kStep))/kStep, right = (f(x+kStep)-f(x))/kStep;
    printf("%10.5f %14.8f %14.8f %14.6f %14.6f %14.6f %12.4g\n", x, v, s, cfd, left, right, std::abs(s-cfd));
  }
}

int main() {
  auto table = make_table();
  probe("radial", [&](double x){return radial_value(table,x);}, [&](double x){return radial_sens(table,x);});
  probe("angular", [&](double x){return angular_value(table,x);}, [&](double x){return angular_sens(table,x);});
  return 0;
}
