/*
    This inline function was designed to get the table info and bias value for
   current input xx! lower:      indicate the lower boundary of the first table;
    upper:      indicate the upper boundary of the first table as well as the
   lower boundary of the second table; max:        indicate the upper boundary
   of the second table; stride0:    indicate the stride of the first table;
    stride1:    indicate the stride of the second table;
    xx:         indicate the inputs value;
    table_idx:  indicate the location of table info of input value xx;
    dd:         indicate the signed distance between the input value and the
   boundary of the tabulated support. It is exactly zero whenever the input is
   inside the tabulated support; otherwise xx/table_idx point at the closest
   boundary of the support and dd carries the remaining displacement, so that
   the table response can be continued outside of the support without breaking
   the relation between the returned value and its derivative (see
   `table_value` / `table_grad` below).
*/
template <typename FPTYPE>
inline void locate_xx(const FPTYPE& lower,
                      const FPTYPE& upper,
                      const FPTYPE& max,
                      const FPTYPE& stride0,
                      const FPTYPE& stride1,
                      FPTYPE& xx,
                      FPTYPE& dd,
                      int& table_idx) {
  // number of intervals stored by the two sub-tables
  const int first_stride = int((upper - lower) / stride0);
  const int second_stride = (int)((max - upper) / stride1);
  // index of the last interval supported by the table
  const int last_idx = first_stride + second_stride - 1;
  dd = (FPTYPE)0.;
  if (xx < lower) {
    // below the tabulated support: stay on the left end of the first interval
    table_idx = 0;
    dd = xx - lower;
    xx = (FPTYPE)0.;
  } else if (xx < upper) {
    table_idx = (int)((xx - lower) / stride0);
    xx -= (table_idx * stride0 + lower);
  } else if (xx < max &&
             first_stride + (int)((xx - upper) / stride1) <= last_idx) {
    table_idx = first_stride + (int)((xx - upper) / stride1);
    xx -= ((table_idx - first_stride) * stride1 + upper);
  } else {
    // beyond the tabulated support: stay on the right end of the last interval
    table_idx = last_idx;
    dd = xx - (upper + (FPTYPE)second_stride * stride1);
    xx = stride1;
  }
}

template <typename FPTYPE>
inline void locate_xx_se_t(const FPTYPE& lower,
                           const FPTYPE& upper,
                           const FPTYPE& min,
                           const FPTYPE& max,
                           const FPTYPE& stride0,
                           const FPTYPE& stride1,
                           FPTYPE& xx,
                           FPTYPE& dd,
                           int& table_idx) {
  // number of intervals stored by the three sub-tables
  const int first_stride = int((lower - min) / stride1);
  const int second_stride = int((upper - lower) / stride0);
  const int third_stride = (int)((max - upper) / stride1);
  // index of the last interval supported by the table
  const int last_idx = first_stride + second_stride + third_stride - 1;
  dd = (FPTYPE)0.;
  if (xx < min) {
    // below the tabulated support: stay on the left end of the first interval
    table_idx = 0;
    dd = xx - min;
    xx = (FPTYPE)0.;
  } else if (xx < lower) {
    table_idx = (int)((xx - min) / stride1);
    xx -= (table_idx * stride1 + min);
  } else if (xx < upper) {
    table_idx = first_stride + (int)((xx - lower) / stride0);
    xx -= ((table_idx - first_stride) * stride0 + lower);
  } else if (xx < max && first_stride + second_stride +
                                 (int)((xx - upper) / stride1) <=
                             last_idx) {
    table_idx = first_stride + second_stride + (int)((xx - upper) / stride1);
    xx -= ((table_idx - first_stride - second_stride) * stride1 + upper);
  } else {
    // beyond the tabulated support: stay on the right end of the last interval
    table_idx = last_idx;
    dd = xx - (upper + (FPTYPE)third_stride * stride1);
    xx = stride1;
  }
}

/*
    The compressed model stores, for every interval and every output component,
   the six coefficients of the fifth-order polynomial that reproduces the
   embedding network on that interval. The three functions below evaluate that
   polynomial and its first two derivatives with respect to the local coordinate
   xx of the interval.
*/
template <typename FPTYPE>
inline FPTYPE table_poly(const FPTYPE* aa, const FPTYPE& xx) {
  return aa[0] +
         (aa[1] + (aa[2] + (aa[3] + (aa[4] + aa[5] * xx) * xx) * xx) * xx) * xx;
}

template <typename FPTYPE>
inline FPTYPE table_poly_grad(const FPTYPE* aa, const FPTYPE& xx) {
  return aa[1] +
         ((FPTYPE)2. * aa[2] +
          ((FPTYPE)3. * aa[3] + ((FPTYPE)4. * aa[4] + (FPTYPE)5. * aa[5] * xx) *
                                    xx) *
              xx) *
             xx;
}

template <typename FPTYPE>
inline FPTYPE table_poly_curv(const FPTYPE* aa, const FPTYPE& xx) {
  return (FPTYPE)2. * aa[2] +
         ((FPTYPE)6. * aa[3] +
          ((FPTYPE)12. * aa[4] + (FPTYPE)20. * aa[5] * xx) * xx) *
             xx;
}

/*
    Table response of one output component and its derivative with respect to
   the input of the embedding network.

    Inside the tabulated support (dd == 0) these are the stored polynomial and
   its derivative. Outside of the support the stored polynomial is not
   constrained by any table sample, so the fifth-order interval is not continued
   there. Instead the response is continued from the boundary of the support
   with the endpoint data the table is built from, i.e. the value, the first and
   the second derivative of the boundary interval:

        value(x) = P(t) + P'(t) * dd + P''(t) * dd^2 / 2
        grad(x)  = P'(t) + P''(t) * dd

   with dd the displacement out of the support. `grad` therefore stays exactly
   the derivative of `value` on the whole real axis, and value, first and second
   derivative remain continuous across the boundary of the support, which is
   what a derivative based molecular dynamics workflow needs from the compressed
   table.
*/
template <typename FPTYPE>
inline FPTYPE table_value(const FPTYPE* aa, const FPTYPE& xx, const FPTYPE& dd) {
  const FPTYPE var = table_poly(aa, xx);
  if (dd == (FPTYPE)0.) {
    return var;
  }
  return var + (table_poly_grad(aa, xx) +
                (FPTYPE)0.5 * table_poly_curv(aa, xx) * dd) *
                   dd;
}

template <typename FPTYPE>
inline FPTYPE table_grad(const FPTYPE* aa, const FPTYPE& xx, const FPTYPE& dd) {
  const FPTYPE var_grad = table_poly_grad(aa, xx);
  if (dd == (FPTYPE)0.) {
    return var_grad;
  }
  return var_grad + table_poly_curv(aa, xx) * dd;
}

template <typename FPTYPE>
inline FPTYPE dot(FPTYPE a[4], FPTYPE b[4]) {
  return a[0] * b[0] + a[1] * b[1] + a[2] * b[2] + a[3] * b[3];
}

