// Generalization harness for the compressed tabulation kernels.
//  * builds tables exactly the way a compressed model does: per interval, the
//    quintic that matches value / 1st / 2nd derivative of a smooth embedding
//    function at the interval endpoints (so the table response is C2 inside the
//    tabulated support and can be compared with the smooth reference);
//  * checks, for every descriptor family and several table configurations, that
//      - the returned sensitivities are the derivatives of the returned values
//        (vector-Jacobian product vs central finite differences),
//      - the second-order kernels are the matching directional derivative,
//      - values and sensitivities stay continuous (no jumps, no kinks),
//      - in-support values reproduce the tabulated smooth function.
#include "tabulate.h"

#include <cmath>
#include <cstdio>
#include <functional>
#include <random>
#include <string>
#include <vector>

namespace {

int g_failures = 0;
int g_checks = 0;

void report(const std::string& what, double err, double tol) {
  ++g_checks;
  bool ok = std::isfinite(err) && err <= tol;
  if (!ok) {
    ++g_failures;
    std::printf("  FAIL %-58s err=%.6g tol=%.3g\n", what.c_str(), err, tol);
  } else {
    std::printf("  ok   %-58s err=%.6g\n", what.c_str(), err);
  }
}

// ---------------------------------------------------------------- smooth model
struct Embedding {  // smooth 1d -> ng function, with analytic derivatives
  int ng;
  std::vector<double> p, q, amp, freq, phase;
  explicit Embedding(int ng_, unsigned seed) : ng(ng_) {
    std::mt19937 gen(seed);
    std::uniform_real_distribution<double> u(-1.0, 1.0);
    for (int m = 0; m < ng; ++m) {
      p.push_back(0.8 + 0.5 * std::fabs(u(gen)));
      q.push_back(u(gen));
      amp.push_back(0.3 * u(gen));
      freq.push_back(1.1 + 0.7 * std::fabs(u(gen)));
      phase.push_back(u(gen));
    }
  }
  double v(int m, double x) const {
    return std::tanh(p[m] * x + q[m]) + amp[m] * std::sin(freq[m] * x + phase[m]);
  }
  double d1(int m, double x) const {
    const double t = std::tanh(p[m] * x + q[m]);
    return p[m] * (1 - t * t) +
           amp[m] * freq[m] * std::cos(freq[m] * x + phase[m]);
  }
  double d2(int m, double x) const {
    const double t = std::tanh(p[m] * x + q[m]);
    return -2 * p[m] * p[m] * t * (1 - t * t) -
           amp[m] * freq[m] * freq[m] * std::sin(freq[m] * x + phase[m]);
  }
};

// interval layout used by the kernels
struct Config {
  bool se_t;  // three sub-tables (se_t / se_t_tebd) or two (se_a / se_r)
  double lower, upper, max, stride0, stride1;
  std::string name;

  std::vector<double> starts() const {  // left end of every stored interval
    std::vector<double> s;
    if (se_t) {
      const int n_pre = int((lower + max) / stride1);
      for (int i = 0; i < n_pre; ++i) s.push_back(-max + i * stride1);
    }
    const int n_fine = int((upper - lower) / stride0);
    for (int i = 0; i < n_fine; ++i) s.push_back(lower + i * stride0);
    const int n_post = int((max - upper) / stride1);
    for (int i = 0; i < n_post; ++i) s.push_back(upper + i * stride1);
    return s;
  }
  std::vector<double> widths() const {
    std::vector<double> w;
    if (se_t) {
      const int n_pre = int((lower + max) / stride1);
      for (int i = 0; i < n_pre; ++i) w.push_back(stride1);
    }
    const int n_fine = int((upper - lower) / stride0);
    for (int i = 0; i < n_fine; ++i) w.push_back(stride0);
    const int n_post = int((max - upper) / stride1);
    for (int i = 0; i < n_post; ++i) w.push_back(stride1);
    return w;
  }
  double support_lo() const { return se_t ? -max : lower; }
  double support_hi() const {
    const std::vector<double> s = starts(), w = widths();
    return s.back() + w.back();
  }
  std::vector<double> info() const {
    return {lower, upper, max, stride0, stride1, -1.0};
  }
};

// Hermite quintic per interval: value / 1st / 2nd derivative matched at both ends
std::vector<double> build_table(const Config& cfg, const Embedding& emb) {
  const std::vector<double> s = cfg.starts(), w = cfg.widths();
  const int ng = emb.ng;
  std::vector<double> table(s.size() * ng * 6, 0.0);
  for (std::size_t l = 0; l < s.size(); ++l) {
    for (int m = 0; m < ng; ++m) {
      const double h = w[l], x0 = s[l], x1 = s[l] + h;
      const double y0 = emb.v(m, x0), y0p = emb.d1(m, x0), y0pp = emb.d2(m, x0);
      const double y1 = emb.v(m, x1), y1p = emb.d1(m, x1), y1pp = emb.d2(m, x1);
      const double a0 = y0, a1 = y0p, a2 = 0.5 * y0pp;
      const double r0 = y1 - (a0 + a1 * h + a2 * h * h);
      const double r1 = y1p - (a1 + 2 * a2 * h);
      const double r2 = y1pp - 2 * a2;
      const double uu = 10 * r0 - 4 * r1 * h + 0.5 * r2 * h * h;
      const double vv = -15 * r0 + 7 * r1 * h - r2 * h * h;
      const double ww = 6 * r0 - 3 * r1 * h + 0.5 * r2 * h * h;
      double* aa = &table[(l * ng + m) * 6];
      aa[0] = a0; aa[1] = a1; aa[2] = a2;
      aa[3] = uu / (h * h * h);
      aa[4] = vv / (h * h * h * h);
      aa[5] = ww / (h * h * h * h * h);
    }
  }
  return table;
}

// interesting sweep points: boundaries, interval joints, interiors, outside
std::vector<double> sweep(const Config& cfg) {
  std::vector<double> pts;
  const std::vector<double> s = cfg.starts(), w = cfg.widths();
  const double lo = cfg.support_lo(), hi = cfg.support_hi();
  for (std::size_t l = 0; l < s.size(); ++l) {
    pts.push_back(s[l]);                  // exactly on a joint
    pts.push_back(s[l] + 0.37 * w[l]);    // interior
    pts.push_back(s[l] + 0.5 * w[l]);
  }
  pts.push_back(cfg.upper);               // sub-table junction
  pts.push_back(hi);                      // right end of the support
  pts.push_back(cfg.max);
  for (double d : {1e-3, 0.09, 0.31, 0.5, 1.0}) {  // outside the support
    pts.push_back(lo - d);
    pts.push_back(hi + d);
  }
  return pts;
}

// -------------------------------------------------------------- generic checks
struct Op {
  int n_in, n_out;
  std::function<std::vector<double>(const std::vector<double>&)> forward;
  std::function<std::vector<double>(const std::vector<double>&,
                                    const std::vector<double>&)> vjp;
  std::function<std::vector<double>(const std::vector<double>&,
                                    const std::vector<double>&)> jvp;
};

double check_vjp(const Op& op, std::vector<double> in,
                 const std::vector<double>& dy, double h) {
  const std::vector<double> g = op.vjp(in, dy);
  double worst = 0.0;
  for (int p = 0; p < op.n_in; ++p) {
    const double x0 = in[p];
    in[p] = x0 + h;
    const std::vector<double> op_plus = op.forward(in);
    in[p] = x0 - h;
    const std::vector<double> op_minus = op.forward(in);
    in[p] = x0;
    double fd = 0.0;
    for (int o = 0; o < op.n_out; ++o) {
      fd += dy[o] * (op_plus[o] - op_minus[o]) / (2 * h);
    }
    worst = std::max(worst, std::fabs(fd - g[p]));
  }
  return worst;
}

double check_jvp(const Op& op, std::vector<double> in,
                 const std::vector<double>& tangent, double h) {
  const std::vector<double> z = op.jvp(in, tangent);
  std::vector<double> plus(in), minus(in);
  for (int p = 0; p < op.n_in; ++p) {
    plus[p] += h * tangent[p];
    minus[p] -= h * tangent[p];
  }
  const std::vector<double> op_plus = op.forward(plus);
  const std::vector<double> op_minus = op.forward(minus);
  double worst = 0.0;
  for (int o = 0; o < op.n_out; ++o) {
    const double fd = (op_plus[o] - op_minus[o]) / (2 * h);
    worst = std::max(worst, std::fabs(fd - z[o]));
  }
  return worst;
}

// value jump / slope kink of one scalar response and of its sensitivity
struct Smoothness {
  double value_jump = 0, value_kink = 0, sens_jump = 0, sens_kink = 0;
};

Smoothness check_smooth(const std::function<double(double)>& val,
                        const std::function<double(double)>& sens,
                        const std::vector<double>& pts, double h) {
  Smoothness sm;
  for (double x : pts) {
    const double vm = val(x - h), v0 = val(x), vp = val(x + h);
    sm.value_jump = std::max(sm.value_jump, std::fabs(vp - vm));
    sm.value_kink = std::max(
        sm.value_kink, std::fabs((vp - v0) / h - (v0 - vm) / h));
    const double gm = sens(x - h), g0 = sens(x), gp = sens(x + h);
    sm.sens_jump = std::max(sm.sens_jump, std::fabs(gp - gm));
    sm.sens_kink =
        std::max(sm.sens_kink, std::fabs((gp - g0) / h - (g0 - gm) / h));
  }
  return sm;
}

std::vector<double> spread(int n, unsigned seed, double lo = -1.0,
                           double hi = 1.0) {
  std::mt19937 gen(seed);
  std::uniform_real_distribution<double> u(lo, hi);
  std::vector<double> v(n);
  for (int i = 0; i < n; ++i) v[i] = u(gen);
  return v;
}

// ------------------------------------------------------------------ se_a family
void test_se_a(const Config& cfg, const Embedding& emb, bool two, bool sorted) {
  const int nloc = 2, nnei = 3, ng = emb.ng;
  const std::vector<double> table = build_table(cfg, emb);
  const std::vector<double> info = cfg.info();
  const int n_x = nloc * nnei, n_em = nloc * nnei * 4;
  const int n_t = two ? nloc * nnei * ng : 0;
  const int n_in = n_x + n_em + n_t, n_out = nloc * 4 * ng;
  const std::vector<double> tw = two ? spread(n_t, 7) : std::vector<double>();

  Op op;
  op.n_in = n_in;
  op.n_out = n_out;
  op.forward = [&](const std::vector<double>& in) {
    std::vector<double> out(n_out);
    deepmd::tabulate_fusion_se_a_cpu<double>(
        out.data(), table.data(), info.data(), in.data(), in.data() + n_x,
        two ? in.data() + n_x + n_em : nullptr, nloc, nnei, ng, sorted);
    return out;
  };
  op.vjp = [&](const std::vector<double>& in, const std::vector<double>& dy) {
    std::vector<double> gx(n_x), gem(n_em), gt(std::max(n_t, 1));
    deepmd::tabulate_fusion_se_a_grad_cpu<double>(
        gx.data(), gem.data(), gt.data(), table.data(), info.data(), in.data(),
        in.data() + n_x, two ? in.data() + n_x + n_em : nullptr, dy.data(),
        nloc, nnei, ng, sorted);
    std::vector<double> g;
    g.insert(g.end(), gx.begin(), gx.end());
    g.insert(g.end(), gem.begin(), gem.end());
    if (two) g.insert(g.end(), gt.begin(), gt.begin() + n_t);
    return g;
  };
  op.jvp = [&](const std::vector<double>& in, const std::vector<double>& t) {
    std::vector<double> z(n_out);
    std::vector<double> zero(std::max(n_t, 1), 0.0);
    deepmd::tabulate_fusion_se_a_grad_grad_cpu<double>(
        z.data(), table.data(), info.data(), in.data(), in.data() + n_x,
        two ? in.data() + n_x + n_em : nullptr, t.data(), t.data() + n_x,
        two ? t.data() + n_x + n_em : zero.data(), nloc, nnei, ng, sorted);
    return z;
  };

  const std::vector<double> pts = sweep(cfg);
  const std::vector<double> dy = spread(n_out, 11);
  const std::vector<double> tangent = spread(n_in, 13);
  double worst_vjp = 0, worst_jvp = 0;
  for (std::size_t base = 0; base < pts.size(); base += n_x) {
    std::vector<double> in(n_in);
    for (int i = 0; i < n_x; ++i) in[i] = pts[(base + i) % pts.size()];
    const std::vector<double> em = spread(n_em, 17 + base);
    for (int i = 0; i < n_em; ++i) in[n_x + i] = em[i];
    for (int i = 0; i < n_t; ++i) in[n_x + n_em + i] = tw[i];
    worst_vjp = std::max(worst_vjp, check_vjp(op, in, dy, 1e-6));
    worst_jvp = std::max(worst_jvp, check_jvp(op, in, tangent, 1e-6));
  }
  const std::string tag = "se_a[" + cfg.name + (two ? ",two" : "") +
                          (sorted ? ",sorted" : "") + "]";
  report(tag + " sensitivity == d(value)", worst_vjp, 1e-6);
  report(tag + " second order == d(value)", worst_jvp, 1e-6);

  // scalar response of one neighbour, as in the public probe
  std::vector<double> in0(n_in, 0.0);
  const std::vector<double> em0 = spread(n_em, 23);
  for (int i = 0; i < n_em; ++i) in0[n_x + i] = em0[i];
  for (int i = 0; i < n_t; ++i) in0[n_x + n_em + i] = tw[i];
  auto value = [&](double x) {
    std::vector<double> in(in0);
    for (int i = 0; i < n_x; ++i) in[i] = x;
    const std::vector<double> out = op.forward(in);
    double v = 0;
    for (int o = 0; o < n_out; ++o) v += dy[o] * out[o];
    return v;
  };
  auto sens = [&](double x) {
    std::vector<double> in(in0);
    for (int i = 0; i < n_x; ++i) in[i] = x;
    const std::vector<double> g = op.vjp(in, dy);
    double v = 0;
    for (int i = 0; i < n_x; ++i) v += g[i];
    return v;
  };
  const Smoothness sm = check_smooth(value, sens, pts, 1e-6);
  report(tag + " value continuous", sm.value_jump, 1e-4);
  report(tag + " value has no kink", sm.value_kink, 1e-4);
  report(tag + " sensitivity continuous", sm.sens_jump, 1e-4);
  report(tag + " sensitivity has no kink", sm.sens_kink, 1e-3);
}

// ------------------------------------------------------------------ se_r family
void test_se_r(const Config& cfg, const Embedding& emb) {
  const int nloc = 2, nnei = 3, ng = emb.ng;
  const std::vector<double> table = build_table(cfg, emb);
  const std::vector<double> info = cfg.info();
  const int n_in = nloc * nnei, n_out = nloc * nnei * ng;
  Op op;
  op.n_in = n_in;
  op.n_out = n_out;
  op.forward = [&](const std::vector<double>& in) {
    std::vector<double> out(n_out);
    deepmd::tabulate_fusion_se_r_cpu<double>(out.data(), table.data(),
                                             info.data(), in.data(), nloc,
                                             nnei, ng);
    return out;
  };
  op.vjp = [&](const std::vector<double>& in, const std::vector<double>& dy) {
    std::vector<double> g(n_in);
    deepmd::tabulate_fusion_se_r_grad_cpu<double>(g.data(), table.data(),
                                                  info.data(), in.data(),
                                                  dy.data(), nloc, nnei, ng);
    return g;
  };
  op.jvp = [&](const std::vector<double>& in, const std::vector<double>& t) {
    std::vector<double> z(n_out);
    deepmd::tabulate_fusion_se_r_grad_grad_cpu<double>(
        z.data(), table.data(), info.data(), in.data(), t.data(), nloc, nnei,
        ng);
    return z;
  };
  const std::vector<double> pts = sweep(cfg);
  const std::vector<double> dy = spread(n_out, 29);
  const std::vector<double> tangent = spread(n_in, 31);
  double worst_vjp = 0, worst_jvp = 0, worst_ref = 0;
  for (std::size_t base = 0; base < pts.size(); base += n_in) {
    std::vector<double> in(n_in);
    for (int i = 0; i < n_in; ++i) in[i] = pts[(base + i) % pts.size()];
    worst_vjp = std::max(worst_vjp, check_vjp(op, in, dy, 1e-6));
    worst_jvp = std::max(worst_jvp, check_jvp(op, in, tangent, 1e-6));
    // in-support values must reproduce the tabulated smooth embedding
    const std::vector<double> out = op.forward(in);
    for (int i = 0; i < n_in; ++i) {
      if (in[i] < cfg.support_lo() || in[i] >= cfg.support_hi()) continue;
      for (int m = 0; m < ng; ++m) {
        worst_ref = std::max(worst_ref,
                             std::fabs(out[(i / nnei) * nnei * ng +
                                           (i % nnei) * ng + m] -
                                       emb.v(m, in[i])));
      }
    }
  }
  const std::string tag = "se_r[" + cfg.name + "]";
  report(tag + " sensitivity == d(value)", worst_vjp, 1e-6);
  report(tag + " second order == d(value)", worst_jvp, 1e-6);
  report(tag + " in-support value == embedding", worst_ref, 1e-6);

  const std::vector<double> dy1 = spread(ng, 37);
  auto value = [&](double x) {
    std::vector<double> out(ng), em = {x};
    deepmd::tabulate_fusion_se_r_cpu<double>(out.data(), table.data(),
                                             info.data(), em.data(), 1, 1, ng);
    double v = 0;
    for (int m = 0; m < ng; ++m) v += dy1[m] * out[m];
    return v;
  };
  auto sens = [&](double x) {
    std::vector<double> g(1), em = {x};
    deepmd::tabulate_fusion_se_r_grad_cpu<double>(g.data(), table.data(),
                                                  info.data(), em.data(),
                                                  dy1.data(), 1, 1, ng);
    return g[0];
  };
  const Smoothness sm = check_smooth(value, sens, pts, 1e-6);
  report(tag + " value continuous", sm.value_jump, 1e-4);
  report(tag + " value has no kink", sm.value_kink, 1e-4);
  report(tag + " sensitivity continuous", sm.sens_jump, 1e-4);
  report(tag + " sensitivity has no kink", sm.sens_kink, 1e-3);
}

// ------------------------------------------------------------------ se_t family
void test_se_t(const Config& cfg, const Embedding& emb) {
  const int nloc = 2, ni = 2, nj = 2, ng = emb.ng;
  const std::vector<double> table = build_table(cfg, emb);
  const std::vector<double> info = cfg.info();
  const int n_in = nloc * ni * nj, n_out = nloc * ng;
  Op op;
  op.n_in = n_in;
  op.n_out = n_out;
  // em_x and em are the same tensor for this family
  op.forward = [&](const std::vector<double>& in) {
    std::vector<double> out(n_out);
    deepmd::tabulate_fusion_se_t_cpu<double>(out.data(), table.data(),
                                             info.data(), in.data(), in.data(),
                                             nloc, ni, nj, ng);
    return out;
  };
  op.vjp = [&](const std::vector<double>& in, const std::vector<double>& dy) {
    std::vector<double> gx(n_in), gem(n_in);
    deepmd::tabulate_fusion_se_t_grad_cpu<double>(
        gx.data(), gem.data(), table.data(), info.data(), in.data(), in.data(),
        dy.data(), nloc, ni, nj, ng);
    for (int i = 0; i < n_in; ++i) gx[i] += gem[i];
    return gx;
  };
  op.jvp = [&](const std::vector<double>& in, const std::vector<double>& t) {
    std::vector<double> z(n_out);
    deepmd::tabulate_fusion_se_t_grad_grad_cpu<double>(
        z.data(), table.data(), info.data(), in.data(), in.data(), t.data(),
        t.data(), nloc, ni, nj, ng);
    return z;
  };
  const std::vector<double> pts = sweep(cfg);
  const std::vector<double> dy = spread(n_out, 41);
  const std::vector<double> tangent = spread(n_in, 43);
  double worst_vjp = 0, worst_jvp = 0;
  for (std::size_t base = 0; base < pts.size(); base += n_in) {
    std::vector<double> in(n_in);
    for (int i = 0; i < n_in; ++i) in[i] = pts[(base + i) % pts.size()];
    worst_vjp = std::max(worst_vjp, check_vjp(op, in, dy, 1e-6));
    worst_jvp = std::max(worst_jvp, check_jvp(op, in, tangent, 1e-6));
  }
  const std::string tag = "se_t[" + cfg.name + "]";
  report(tag + " sensitivity == d(value)", worst_vjp, 1e-6);
  report(tag + " second order == d(value)", worst_jvp, 1e-6);

  auto value = [&](double x) {
    std::vector<double> in(n_in, x);
    const std::vector<double> out = op.forward(in);
    double v = 0;
    for (int o = 0; o < n_out; ++o) v += dy[o] * out[o];
    return v;
  };
  auto sens = [&](double x) {
    std::vector<double> in(n_in, x);
    const std::vector<double> g = op.vjp(in, dy);
    double v = 0;
    for (int i = 0; i < n_in; ++i) v += g[i];
    return v;
  };
  const Smoothness sm = check_smooth(value, sens, pts, 1e-6);
  report(tag + " value continuous", sm.value_jump, 1e-4);
  report(tag + " value has no kink", sm.value_kink, 1e-4);
  report(tag + " sensitivity continuous", sm.sens_jump, 1e-4);
  report(tag + " sensitivity has no kink", sm.sens_kink, 1e-3);
}

// ------------------------------------------------------------- se_t_tebd family
