  };
  const std::vector<double> pts = sweep(cfg);
  const std::vector<double> dy = spread(n_out, 47);
  const std::vector<double> tangent = spread(n_in, 53);
  double worst_vjp = 0, worst_jvp = 0, worst_ref = 0;
  for (std::size_t base = 0; base < pts.size(); base += n_in) {
    std::vector<double> in(n_in);
    for (int i = 0; i < n_in; ++i) in[i] = pts[(base + i) % pts.size()];
    worst_vjp = std::max(worst_vjp, check_vjp(op, in, dy, 1e-6));
    worst_jvp = std::max(worst_jvp, check_jvp(op, in, tangent, 1e-6));
    const std::vector<double> out = op.forward(in);
    for (int i = 0; i < n_in; ++i) {
      if (in[i] < cfg.support_lo() || in[i] >= cfg.support_hi()) continue;
      for (int m = 0; m < ng; ++m) {
        worst_ref =
            std::max(worst_ref, std::fabs(out[i * ng + m] - emb.v(m, in[i])));
      }
    }
  }
  const std::string tag = "se_t_tebd[" + cfg.name + "]";
  report(tag + " sensitivity == d(value)", worst_vjp, 1e-6);
  report(tag + " second order == d(value)", worst_jvp, 1e-6);
  report(tag + " in-support value == embedding", worst_ref, 1e-6);

  auto value = [&](double x) {
    std::vector<double> in(n_in, x);
    const std::vector<double> out = op.forward(in);
    double v = 0;
    for (int o = 0; o < n_out; ++o) v += dy[o] * out[o];
    return v;
  };
  auto sens = [&](double x) {
    std::vector<double> in(n_in, x);
    const std::vector<double> g = op.vjp(in, dy);
    double v = 0;
    for (int i = 0; i < n_in; ++i) v += g[i];
    return v;
  };
  const Smoothness sm = check_smooth(value, sens, pts, 1e-6);
  report(tag + " value continuous", sm.value_jump, 1e-4);
  report(tag + " value has no kink", sm.value_kink, 1e-4);
  report(tag + " sensitivity continuous", sm.sens_jump, 1e-4);
  report(tag + " sensitivity has no kink", sm.sens_kink, 1e-3);
}

// --------------------------------------------------- se_a sorted/unsorted match
void test_unloop(const Config& cfg, const Embedding& emb) {
  const int nloc = 1, nnei = 4, ng = emb.ng;
  const std::vector<double> table = build_table(cfg, emb);
  const std::vector<double> info = cfg.info();
  std::vector<double> em_x(nloc * nnei), em(nloc * nnei * 4, 0.0);
  const double interior = 0.5 * (cfg.lower + cfg.upper);
  em_x[0] = interior;
  em[0] = 0.9; em[1] = 0.2; em[2] = -0.3; em[3] = 0.15;
  const double pad = cfg.support_hi();  // identical padded tail
  for (int j = 1; j < nnei; ++j) {
    em_x[j] = pad;
    em[j * 4 + 0] = 0.4;
  }
  std::vector<double> out_s(nloc * 4 * ng), out_u(nloc * 4 * ng);
  deepmd::tabulate_fusion_se_a_cpu<double>(out_s.data(), table.data(),
                                           info.data(), em_x.data(), em.data(),
                                           nullptr, nloc, nnei, ng, true);
  deepmd::tabulate_fusion_se_a_cpu<double>(out_u.data(), table.data(),
                                           info.data(), em_x.data(), em.data(),
                                           nullptr, nloc, nnei, ng, false);
  double worst = 0;
  for (std::size_t i = 0; i < out_s.size(); ++i)
    worst = std::max(worst, std::fabs(out_s[i] - out_u[i]));
  report("se_a[" + cfg.name + "] sorted shortcut == plain loop", worst, 1e-12);

  const std::vector<double> dy = spread(nloc * 4 * ng, 59);
  std::vector<double> gx_s(nloc * nnei), gem_s(nloc * nnei * 4);
  std::vector<double> gx_u(nloc * nnei), gem_u(nloc * nnei * 4);
  deepmd::tabulate_fusion_se_a_grad_cpu<double>(
      gx_s.data(), gem_s.data(), nullptr, table.data(), info.data(),
      em_x.data(), em.data(), nullptr, dy.data(), nloc, nnei, ng, true);
  deepmd::tabulate_fusion_se_a_grad_cpu<double>(
      gx_u.data(), gem_u.data(), nullptr, table.data(), info.data(),
      em_x.data(), em.data(), nullptr, dy.data(), nloc, nnei, ng, false);
  double worst_g = 0;
  for (int j = 0; j < nloc * nnei; ++j)
    worst_g = std::max(worst_g, std::fabs(gx_s[j] - (j == 0 ? gx_u[0] : 0.0) -
                                          (j == 1 ? gx_u[1] + gx_u[2] + gx_u[3]
                                                  : 0.0)));
  report("se_a[" + cfg.name + "] sorted shortcut grad consistent", worst_g,
         1e-12);
}

// ------------------------------------------------------------------ float32 run
void test_float(const Config& cfg, const Embedding& emb) {
  const int nloc = 1, nnei = 2, ng = emb.ng;
  const std::vector<double> td = build_table(cfg, emb);
  std::vector<float> table(td.begin(), td.end());
  const std::vector<double> id = cfg.info();
  std::vector<float> info(id.begin(), id.end());
  std::vector<float> em = {(float)(cfg.support_hi() + 0.2),
                           (float)(cfg.support_lo() - 0.2)};
  std::vector<float> out(nloc * nnei * ng), dy(nloc * nnei * ng, 1.0f),
      g(nloc * nnei);
  deepmd::tabulate_fusion_se_r_cpu<float>(out.data(), table.data(), info.data(),
                                          em.data(), nloc, nnei, ng);
  deepmd::tabulate_fusion_se_r_grad_cpu<float>(g.data(), table.data(),
                                               info.data(), em.data(),
                                               dy.data(), nloc, nnei, ng);
  double worst = 0;
  for (float v : out) worst = std::max(worst, std::isfinite(v) ? 0.0 : 1.0);
  for (float v : g) worst = std::max(worst, std::isfinite(v) ? 0.0 : 1.0);
  // float32 finite difference, loose tolerance
  const float h = 1e-2f;
  for (int j = 0; j < nnei; ++j) {
    std::vector<float> ep(em), em2(em);
    ep[j] += h;
    em2[j] -= h;
    std::vector<float> op_p(nloc * nnei * ng), op_m(nloc * nnei * ng);
    deepmd::tabulate_fusion_se_r_cpu<float>(op_p.data(), table.data(),
                                            info.data(), ep.data(), nloc, nnei,
                                            ng);
    deepmd::tabulate_fusion_se_r_cpu<float>(op_m.data(), table.data(),
                                            info.data(), em2.data(), nloc,
                                            nnei, ng);
    double fd = 0;
    for (int o = 0; o < nloc * nnei * ng; ++o)
      fd += (op_p[o] - op_m[o]) / (2 * h);
    worst = std::max(worst, std::fabs(fd - g[j]));
  }
  report("se_r[" + cfg.name + "] float32 outside support", worst, 1e-2);
}

}  // namespace

int main() {
  std::vector<Config> two_table = {
      {false, -1.0, 1.0, 2.8, 0.5, 0.6, "probe"},
      {false, -0.8, 0.6, 2.2, 0.35, 0.4, "cfgA"},
      {false, 0.05, 0.35, 1.55, 0.05, 0.3, "cfgB"},
      {false, -2.0, -0.5, 4.0, 0.25, 0.75, "cfgC"},
      {false, -1.0, 1.0, 2.75, 0.5, 0.6, "ragged"},
  };
  std::vector<Config> three_table = {
      {true, -0.6, 0.6, 1.8, 0.3, 0.4, "tA"},
      {true, -1.0, 1.0, 3.0, 0.5, 1.0, "tB"},
      {true, -0.4, 0.8, 2.0, 0.2, 0.4, "tC"},
  };
  const Embedding emb(3, 20240814u);
  const Embedding emb2(5, 777u);

  for (const Config& cfg : two_table) {
    std::printf("== %s (two sub-tables) ==\n", cfg.name.c_str());
    test_se_a(cfg, emb, false, false);
    test_se_a(cfg, emb2, true, false);
    test_se_a(cfg, emb, false, true);
    test_se_r(cfg, emb, false ? 0 : 0 == 0 ? 0 : 0), void();
  }
  for (const Config& cfg : two_table) {
    test_se_r(cfg, emb);
    test_unloop(cfg, emb);
    test_float(cfg, emb);
  }
  for (const Config& cfg : three_table) {
    std::printf("== %s (three sub-tables) ==\n", cfg.name.c_str());
    test_se_t(cfg, emb);
    test_se_t_tebd(cfg, emb2);
  }
  std::printf("\n%d checks, %d failures\n", g_checks, g_failures);
  return g_failures == 0 ? 0 : 1;
}
