// Robustness probe for degenerate / ragged table configurations.
//  * the table is allocated with exactly the number of rows implied by the
//    configuration, so any read outside of the stored rows is caught by ASan;
//  * the reported sensitivity is compared with central finite differences of
//    the reported value, everywhere including far outside the support.
#include "tabulate.h"

#include <cmath>
#include <cstdio>
#include <random>
#include <vector>

namespace {
int g_fail = 0, g_checks = 0;

struct Cfg {
  const char* name;
  double lower, upper, max, stride0, stride1;
  int rows_two;    // rows of the two sub-table (se_a / se_r) layout
  int rows_three;  // rows of the three sub-table (se_t) layout
};

std::vector<double> make_table(int rows, int ng, unsigned seed) {
  std::mt19937 gen(seed);
  std::uniform_real_distribution<double> u(-1., 1.);
  std::vector<double> t(rows * ng * 6);
  for (size_t i = 0; i < t.size(); ++i) {
    t[i] = u(gen);
  }
  return t;
}

void check(const char* what, double err, double tol) {
  ++g_checks;
  bool ok = std::isfinite(err) && err <= tol;
  if (!ok) {
    ++g_fail;
  }
  std::printf("  %-4s %-58s err=%g\n", ok ? "ok" : "FAIL", what, err);
}

// value / sensitivity of se_r for a single neighbor, contracted with dy = 1
double se_r_value(const Cfg& c, const std::vector<double>& tb, int ng,
                  double x) {
  std::vector<double> info = {c.lower, c.upper, c.max, c.stride0, c.stride1,
                              c.lower};
  std::vector<double> out(ng), em = {x};
  deepmd::tabulate_fusion_se_r_cpu<double>(out.data(), tb.data(), info.data(),
                                           em.data(), 1, 1, ng);
  double s = 0.;
  for (int k = 0; k < ng; ++k) {
    s += out[k];
  }
  return s;
}

double se_r_grad(const Cfg& c, const std::vector<double>& tb, int ng, double x) {
  std::vector<double> info = {c.lower, c.upper, c.max, c.stride0, c.stride1,
                              c.lower};
  std::vector<double> dy(ng, 1.), em = {x}, dy_dem(1, 0.);
  deepmd::tabulate_fusion_se_r_grad_cpu<double>(dy_dem.data(), tb.data(),
                                                info.data(), em.data(),
                                                dy.data(), 1, 1, ng);
  return dy_dem[0];
}

// value / sensitivity of se_t_tebd (three sub-table layout), dy = 1
double se_t_value(const Cfg& c, const std::vector<double>& tb, int ng,
                  double x) {
  std::vector<double> info = {c.lower, c.upper, c.max, c.stride0, c.stride1,
                              c.lower};
  std::vector<double> out(ng), em_x = {x};
  deepmd::tabulate_fusion_se_t_tebd_cpu<double>(
      out.data(), tb.data(), info.data(), em_x.data(), c.max, 1, 1, 1, ng);
  double s = 0.;
  for (int k = 0; k < ng; ++k) {
    s += out[k];
  }
  return s;
}

double se_t_grad(const Cfg& c, const std::vector<double>& tb, int ng, double x) {
  std::vector<double> info = {c.lower, c.upper, c.max, c.stride0, c.stride1,
                              c.lower};
  std::vector<double> dy(ng, 1.), em_x = {x}, dy_dem_x(1, 0.), dy_dem(1, 0.);
  deepmd::tabulate_fusion_se_t_tebd_grad_cpu<double>(
      dy_dem_x.data(), dy_dem.data(), tb.data(), info.data(), em_x.data(),
      dy.data(), c.max, 1, 1, 1, ng);
  return dy_dem_x[0] + dy_dem[0];
}
}  // namespace

int main() {
  const int ng = 4;
  // rows_two   = int((upper-lower)/stride0) + int((max-upper)/stride1)
  // rows_three = int((lower-min)/stride1) + int((upper-lower)/stride0)
  //              + int((max-upper)/stride1) with min = -max
  const Cfg cfgs[] = {
      // second/third sub-table stores no interval at all
      {"no upper sub-table", -1.0, 1.0, 1.05, 0.5, 0.6, 4, 7},
      // first sub-table of the two sub-table layout stores one interval only
      {"single fine interval", -1.0, -0.5, 1.1, 0.5, 0.6, 4, 6},
      // ragged: (max-upper) is not a multiple of stride1
      {"ragged upper range", -1.0, 1.0, 2.75, 0.5, 0.6, 6, 10},
      // regular configuration, for reference
      {"regular", -1.0, 1.0, 2.8, 0.5, 0.6, 7, 11},
  };
  for (const Cfg& c : cfgs) {
    std::printf("== %s (lower=%g upper=%g max=%g stride0=%g stride1=%g) ==\n",
                c.name, c.lower, c.upper, c.max, c.stride0, c.stride1);
    const std::vector<double> tb2 = make_table(c.rows_two, ng, 11);
    const std::vector<double> tb3 = make_table(c.rows_three, ng, 23);
    const double h = 1e-6;
    double worst_r = 0., worst_t = 0.;
    for (int i = 0; i <= 900; ++i) {
      // sweep well outside of the support on both sides
      const double x = c.lower - 1.0 + i * (c.max - c.lower + 3.0) / 900.;
      // stay away from the knots, where the (random) table is discontinuous
      // by construction and finite differences are meaningless
      double t = std::fabs(std::fmod(x - c.lower, c.stride0));
      double t1 = std::fabs(std::fmod(x - c.upper, c.stride1));
      if (std::min(t, c.stride0 - t) < 1e-3 ||
          std::min(t1, c.stride1 - t1) < 1e-3) {
        continue;
      }
      const double fd_r =
          (se_r_value(c, tb2, ng, x + h) - se_r_value(c, tb2, ng, x - h)) /
          (2 * h);
      worst_r = std::max(worst_r, std::fabs(fd_r - se_r_grad(c, tb2, ng, x)));
      const double fd_t =
          (se_t_value(c, tb3, ng, x + h) - se_t_value(c, tb3, ng, x - h)) /
          (2 * h);
      worst_t = std::max(worst_t, std::fabs(fd_t - se_t_grad(c, tb3, ng, x)));
    }
    check("se_r sensitivity == d(value) (in and out of support)", worst_r, 1e-5);
    check("se_t sensitivity == d(value) (in and out of support)", worst_t, 1e-5);
  }
  std::printf("\n%d checks, %d failures\n", g_checks, g_fail);
  return g_fail != 0;
}
